/* @lc app=leetcode id=3636 lang=kotlin */ class Solution { fun ad(cnt: IntArray, bk: Array<java.util.TreeSet<Int>>, mf: IntArray, v: Int) = cnt[v].let { f -> (if (f > 0) bk[f].remove(v) else false).let { bk[f + 1].add(v) }.also { cnt[v] = f + 1 }.also { if (f + 1 > mf[0]) mf[0] = f + 1 } } fun rm(cnt: IntArray, bk: Array<java.util.TreeSet<Int>>, mf: IntArray, v: Int) = cnt[v].let { f -> bk[f].remove(v).also { if (f > 1) bk[f - 1].add(v) }.also { cnt[v] = f - 1 }.also { if (bk[mf[0]].isEmpty() && mf[0] > 0) mf[0]-- } } fun subarrayMajority(nums: IntArray, queries: Array<IntArray>): IntArray = nums.distinct().sorted().let { vals -> nums.map { vals.binarySearch(it) }.let { a -> IntArray(vals.size).let { cnt -> Array(nums.size + 2) { java.util.TreeSet<Int>() }.let { bk -> IntArray(1).let { mf -> Math.max(1, (nums.size / Math.sqrt(queries.size.toDouble())).toInt()).let { B -> queries.indices.sortedWith(compareBy<Int>({ queries[it][0] / B }, { if ((queries[it][0] / B) % 2 == 0) queries[it][1] else -queries[it][1] })).let { ord -> IntArray(queries.size).also { res -> ord.fold(0 to -1) { (cl, cr), qi -> queries[qi][0].let { l -> queries[qi][1].let { r -> (cl - 1 downTo l).forEach { i -> ad(cnt, bk, mf, a[i]) }.let { (cr + 1..r).forEach { i -> ad(cnt, bk, mf, a[i]) } }.let { (cl until l).forEach { i -> rm(cnt, bk, mf, a[i]) } }.let { (cr downTo r + 1).forEach { i -> rm(cnt, bk, mf, a[i]) } }.let { res[qi] = if (mf[0] >= queries[qi][2]) vals[bk[mf[0]].first()] else -1 }.let { l to r } } } } } } } } } } } } }